func All() []Operation {
	result := make([]Operation, len(catalog))
	copy(result, catalog)
	for index := range result {
		result[index].SuccessStatuses = append([]int(nil), result[index].SuccessStatuses...)
		result[index].ErrorCodes = make(map[int][]string, len(catalog[index].ErrorCodes))
		for status, codes := range catalog[index].ErrorCodes {
			result[index].ErrorCodes[status] = append([]string(nil), codes...)
		}
		result[index].Security = make([][]string, len(result[index].Security))
		for alternative := range result[index].Security {
			result[index].Security[alternative] = append([]string(nil), catalog[index].Security[alternative]...)
		}
		result[index].PathParameters = append([]PathParameter(nil), catalog[index].PathParameters...)
		for parameter := range result[index].PathParameters {
			if details := catalog[index].PathParameters[parameter].NotFoundDetails; details != nil {
				result[index].PathParameters[parameter].NotFoundDetails = make(map[string]string, len(details))
				for key, value := range details {
					result[index].PathParameters[parameter].NotFoundDetails[key] = value
				}
			}
		}
	}
	return result
}
